    [2] = {s = {["|1"] = "Speak to Collet for a cutscene.", ["|2"] = "Check the Door: House to the West of Collet for another cutscene (to the right of Marble Bridge).", ["|3"] = "The Key Item you need to complete this quest can only be obtained by completing the quest Deal with Tenshodo.", ["|4"] = "Check the Door: House West of Collet again to complete the quest."}},
