    [5] = {s = {["|1"] = "Examine the Door: Merchant's House on the second floor, Lower Jeuno (G-11), above the chocobo stables by Home Point #1.", ["|2"] = "(Optional) Speak to Shalott, Upper Jeuno (G-7) (Outside Chocobo Stables, next to Mapitoto) for a cutscene.", ["|3"] = "Examine the Night Flowers down the ramp in Qufim Island (F-8) between 21:30 and 4:00 for a cutscene.", ["|4"] = "Examine the Door: Merchant's House in Lower Jeuno for a cutscene and your rewards."}},
