    [7] = {s = {["|1"] = "Talk to Naruru, Teigero-Bangero, or Panta-Putta located in the merchant's house in Lower Jeuno (G-10), for a cutscene.", ["|2"] = "Talk to Panta-Putta.", ["|3"] = "Return to Panta-Putta to complete the quest."}},
    [8] = {s = {["|2"] = "Speak to Apururu, Windurst Woods (H-9) for a cutscene.", ["|3"] = "Head to West Sarutabaruta (F-11) and enter the Outer Horutoto Ruins (Dahlia Tower).", ["|5"] = "Give the Ten of Cups item to Apururu.", ["|6"] = "(Optional) return to Monberaux for some extra dialogue.", ["|7"] = "Return to Panta-Putta, Lower Jeuno (G-10) to complete this quest."}},
    [9] = {s = {["|1"] = "Kurou-Morou is the fortune teller in Lower Jeuno above the Auction House.", ["|3"] = "With the Lens in your possession, head to the Maze of Shakhrami.", ["|4"] = "Go to (G-5) on the first map, which is east of the exit to Attohwa Chasm.", ["|5"] = "At the top of the path, you'll find a Rockwell.", ["|6"] = "Trade your Ahriman Lens to the Rockwell, and you'll get the message \"You submerged the Ahriman Lens into the pool of water.\"", ["|8"] = "Head back to Kurou-Morou and trade him your Divination Sphere."}},
    [10] = {s = {["|1"] = "Speak to Chululu in Lower Jeuno (I-8).", ["|2"] = "You will randomly be given five of one of the following cards:", ["|4"] = "Trade all four cards to Chululu for your measly reward.", ["|5"] = "Every real-life day you can obtain another random card from speaking with Chululu.", ["|6"] = "Note: Speak with Chululu again to obtain the All in the Cards quest."}},
    [11] = {s = {["|1"] = "Speak to Mertaire at Merry Minstrel in Lower Jeuno (I-8).", ["|4"] = "Travel to Buburimu Peninsula at (G-9) and examine the Song Runes for a cutscene.", ["|5"] = "Trade a Parchment to the Song Runes in Buburimu Peninsula at (G-9) for a Poetic Parchment and to complete the quest."}},
    [12] = {s = {["|1"] = "Return to Mertaire and trade the Poetic Parchment to him for a cutscene and your reward."}},
    [13] = {s = {["|2"] = "Speak to her one game day after testing your compatibility 3 times and she will give you this quest.", ["|3"] = "Chululu gives you Magic trash.", ["|4"] = "The Magic trash can only be disposed of in the Incinerator in Garlaige Citadel.", ["|6"] = "To reach the Incinerator, pass through the first two Banishing Gates in Garlaige Citadel.", ["|8"] = "Speak with Mashira who will dispose of the trash for you.", ["|9"] = "Return to Chululu for your reward."}},
    [14] = {s = {["|1"] = "After completing Your Crystal Ball, have Kurou-Morou read your fortune on at least three different game days.", ["|2"] = "Asking for your fourth reading will trigger this quest.", ["|3"] = "Trade a Horn Hairpin to Kurou-Morou to complete the quest."}},
    [15] = {s = {["|1"] = "Note: This quest is only offered to one player per Vana'diel Day, per World.", ["|2"] = "Speak to Zauko in Lower Jeuno at (I-6) between 18:03 and 21:00.", ["|3"] = "You must light all of the Streetlamps in Lower Jeuno before 01:00.", ["|4"] = "Repeating this quest a second time grants the Lamp lighter's membership card."}},
    [16] = {s = {["|1"] = "Speak to Naruru to begin this quest.", ["|2"] = "Once you have the Super soup pot, speak to Naruru for your reward."}},
    [17] = {s = {["|3"] = "Select the third, blank line of dialogue.", ["|4"] = "Head to Port Bastok and into Warehouse #2 upper level.", ["|5"] = "Once inside, talk to Jabbar to receive the Tenshodo application form.", ["|6"] = "Return to Ghebi Damomohe to receive a Tenshodo Invite and Tenshodo Member's Card.", ["|7"] = "Search the Auction House (AH > Others > Misc.) for a Tenshodo Invite and trade it to Ghebi Damomohe to complete the quest."}},
    [18] = {s = {["|1"] = "Speak to Naruru, Teigero-Bangero, and Panta-Putta.", ["|2"] = "Speak to Bozz, Upper Jeuno (G-9)", ["|3"] = "Speak to Monberaux, Upper Jeuno (G-10 in the infirmary) to get a cutscene.", ["|4"] = "After the cutscene, the quest will be completed and you will receive your reward."}},
    [19] = {s = {["|1"] = "Complete the prior quests Chocobo's Wounds and Save My Son.", ["|2"] = "Speak to Brutus in Upper Jeuno (G-7) for a cutscene.", ["|3"] = "(Optional) Visiting the Merchant's House again from here on out will give you a brief scene of their appreciation."}},
    [20] = {s = {["|3"] = "Travel through the tunnel in Valkurm Dunes (C-6) to the \"Secret Beach\" and examine the Song Runes (B-7) for a last cutscene."}},
    [21] = {s = {["|1"] = "After completing the previous quest, speak to Galmut by interacting with the Door: House targetable location in Upper Jeuno at (G-7).", ["|2"] = "This quest will then be completed."}},
    [22] = {s = {["|1"] = "Rouliette in the Goddess Temple will agree to make you a candle if you bring her a Lanolin Cube.", ["|2"] = "Trade her the Lanolin Cube to complete the quest."}},
    [23] = {s = {["|1"] = "Karl tells you that he will give you a Wonder Magic Set if you bring him a White Rock.", ["|2"] = "Trade a White Rock to Karl and he will give you the Wonder Magic Set."}},
    [24] = {s = {["|1"] = "Radeivepart requests that you bring him a Flame Degen.", ["|2"] = "A Flame Degen can be obtained in many ways:", ["|3"] = "Trade the Flame Degen to Radeivepart to complete the quest."}},
    [25] = {s = {["|1"] = "Speak to Imasuke to begin this quest.", ["|2"] = "Head to Qufim Island and kill Dancing Weapons until you obtain a Kaiser Sword.", ["|3"] = "Trade the Kaiser Sword to Imasuke to complete this quest."}},
    [26] = {s = {["|1"] = "Speak to Garnev once you have started the A Clock Most Delicate quest to begin this quest.", ["|2"] = "Trade him a Gold Orcmask to complete the quest."}},
    [31] = {s = {["|1"] = "Speak to Sattal-Mansal to begin this quest.", ["|2"] = "Head to Beadeaux and kill De'Vyu Headhunter (I-9/I-10) to obtain a Quadav Charm.", ["|3"] = "Trade the Quadav Charm to Sattal-Mansal to complete this quest."}},
    [32] = {s = {["|1"] = "Speak to Sattal-Mansal to begin this quest.", ["|2"] = "Head to Beadeaux and kill Go'Bhu Gascon (F-6) to obtain a Quadav Augury Shell.", ["|3"] = "Return the Quadav Augury Shell to Sattal-Mansal for your reward."}},
    [42] = {s = {["|1"] = "Speak to Guttrix, who will offer to make you Race Specific Equipment (RSE) if you bring him a Magical pattern.", ["|2"] = "Each race is given a game week (Firesday to Darksday) to find a pattern.", ["|3"] = "Turn the pattern into Guttrix, who will give you the option to craft it into one of the following four (4) armors:", ["|4"] = "All four armor pieces can be upgraded via the event Strange Happenings in Vana'diel.", ["|5"] = "In addition to the armor, there are RSE ammo pieces for players if they wish to obtain them.", ["|6"] = "During the correct time for your RSE pattern you must simply head to your correct zone and find a ??? on the ground.", ["|7"] = "Chest may also spawn near Morbolger on map 3.", ["|8"] = "Aroma Leech ??? are not marked on the maps, the locations are:"}},
    [43] = {s = {["|1"] = "Talk to Zona Shodhun to start the quest.", ["|2"] = "She won't come out and say it at first, but she would like a Yellow Rock.", ["|3"] = "Yellow Rock can be bought off auction houses; Materials > Goldsmithing.", ["|4"] = "Trade it to her to complete the quest."}},
    [46] = {s = {["|1"] = "Travel to the Durable Shields shop and speak with Guslam located at (H-8) on White Mage to begin the quest.", ["|10"] = "Go to Port Jeuno and head to the crates near the AH and Jeuno Duty-Free Shop at (H-8).", ["|11"] = "Click on the ??? to receive a cutscene.", ["|12"] = "Travel to Castle Zvahl Baileys and go to (F-8) on the first map.", ["|13"] = "Click on one of the torches to spawn Dark Spark.", ["|14"] = "Once Dark Spark is defeated, examine one of the torches for the Key Item Shadow flames.", ["|15"] = "Return to Port Jeuno and examine the ??? again.", ["|3"] = "Go to Beadeaux and find a Treasure Coffer.", ["|4"] = "Either obtain a Beadeaux Coffer Key or pick the lock as a Thief.", ["|5"] = "You will receive a key item Old gauntlets from the coffer.", ["|6"] = "Return to Upper Jeuno and speak to Guslam.", ["|7"] = "If this is your first AF you must do the following, otherwise skip these steps:"}},
    [53] = {s = {["|1"] = "Travel to the Durable Shields shop and speak with Guslam located at (H-8) on Bard to begin the quest.", ["|10"] = "Click on one of the torches to spawn Dark Spark.", ["|11"] = "Once Dark Spark is defeated, examine the same torch you used to spawn it.", ["|12"] = "Return to Port Jeuno and examine the ??? again.", ["|2"] = "Curio Vendor Moogle sells Zvahl Coffer Key (please note \"Rhapsody in Umber\" is required).", ["|3"] = "Go to Castle Zvahl Baileys", ["|4"] = "You will receive a key item Old gauntlets from the coffer.", ["|5"] = "Return to Upper Jeuno and speak to Guslam.", ["|6"] = "If this is your first AF, you must do the following.", ["|7"] = "Go to Port Jeuno and head to the crates near the AH and Jeuno Duty-Free Shop at (H-8).", ["|8"] = "Click on the ??? to receive a cutscene.", ["|9"] = "Travel to Castle Zvahl Baileys and go to (F-8) on the first map."}},
    [55] = {s = {["|1"] = "Travel to the Durable Shields shop and speak with Guslam located at (H-8) on Samurai to begin the quest.", ["|10"] = "Go to Port Jeuno and head to the crates near the AH and Jeuno Duty-Free Shop at (H-8).", ["|12"] = "Travel to Castle Zvahl Baileys and go to (F-8) on the first map.", ["|14"] = "Once Dark Spark is defeated, examine one of the torches for the Key Item Shadow flames.", ["|15"] = "Return to Port Jeuno and examine the ??? again.", ["|2"] = "Go to Kuftal Tunnel.", ["|3"] = "Either obtain a Kuftal Coffer Key or pick the lock as a Thief.", ["|5"] = "You will receive a key item Old gauntlets from the coffer.", ["|6"] = "Return to Upper Jeuno and speak to Guslam.", ["|7"] = "If this is your first AF you must do the following, otherwise skip these steps:"}},
    [56] = {s = {["|1"] = "Travel to \"Durable Shields\" in Upper Jeuno and speak with Guslam located at (H-8) to begin the quest.", ["|10"] = "Speak to Deadly Minnow inside of the Durable Shields shop.", ["|11"] = "Head to Lower Jeuno inside the Tenshodo area.", ["|13"] = "Go to Port Jeuno and head to the crates near the AH and Jeuno Duty-Free Shop at (H-8).", ["|15"] = "Travel to Castle Zvahl Baileys and go to (F-8) on the first map.", ["|19"] = "Once Dark Spark is defeated, examine the same torch you used to spawn it.", ["|2"] = "Go to Ifrit's Cauldron", ["|21"] = "Return to Port Jeuno and examine the ??? again.", ["|5"] = "Either obtain a Cauldron Coffer Key and use it to open one of the chests found in the area, or pick the lock as a Thief.", ["|8"] = "You will receive a Old gauntlets from the coffer.", ["|9"] = "Return to Upper Jeuno and speak to Guslam."}},
    [58] = {s = {["|10"] = "If this is your first AF you must do the following, otherwise skip these steps:", ["|11"] = "Go to Port Jeuno and head to the crates near the AH and Jeuno Duty-Free Shop at (H-8).", ["|13"] = "Travel to Castle Zvahl Baileys and go to (F-8) on the first map.", ["|15"] = "Once Dark Spark is defeated, examine one of the torches for the key item Shadow flames.", ["|16"] = "Return to Port Jeuno and examine the ??? again.", ["|4"] = "Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) on Summoner to begin the quest.", ["|5"] = "Head to the Sea Serpent Grotto:", ["|8"] = "Find and open a Coffer in one of the locations mentioned above.", ["|9"] = "Return to Upper Jeuno and speak to Guslam."}},
    [59] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|13"] = "This fight is against Yallery Brown, a sapling.", ["|14"] = "Go back and speak with Brutus to receive your reward.", ["|2"] = "Speaking with Brutus will grant you the key item Weapons Training Guide as well as the Pick of Trials.", ["|6"] = "Trade the Pick of Trials back to Brutus.", ["|7"] = "Bring some form of Sneak and Invisible with you and head to the Temple of Uggalepih.", ["|8"] = "If you enter the temple conventionally from the Jungle."}},
    [60] = {s = {["|1"] = "Speak to Brutus as a level 40 or higher Beastmaster.", ["|2"] = "Kill monsters on the 7th to 10th floor of Upper Delkfutt's Tower until you get a Delkfutt Chest Key", ["|3"] = "Use the key to open a chest in the zone to receive a Guiding bell.", ["|4"] = "Return to Brutus for your reward."}},
    [61] = {s = {["|1"] = "Speak to Brutus at (G-7) in Upper Jeuno who will give you three Aquaflora Key Items.", ["|4"] = "After defeating Dabotz's Ghost, check the pool at (F-5) again.", ["|5"] = "Return to Brutus for a cutscene.", ["|7"] = "Use the key to open a chest inside the castle to receive a Beast Collar.", ["|8"] = "Trade the Beast Collar to the Opo-opo NPC Tebhi.", ["|9"] = "Return to Brutus for your reward."}},
    [62] = {s = {["|1"] = "Examine the Door:Merchant's House at (G-11) on the upper level behind Greyson in Lower Jeuno for a cutscene (HP #1).", ["|2"] = "Trade a piece of Mahogany Lumber to Osker near the chocobos and Brutus at (G-7) in Upper Jeuno.", ["|3"] = "Zone into Batallia Downs from Beaucedine Glacier and enter The Eldieme Necropolis from the (F-5) entrance.", ["|4"] = "Once inside, head to (D-4) and, if you are low level, clear the room before checking the north east sarcophagus.", ["|5"] = "Examining the sarcophagus will spawn three NM's:", ["|6"] = "Once defeated examine the sarcophagus for a cutscene and your reward."}},
    [63] = {s = {["|1"] = "Travel to Ranguemont Pass and head to the pool at E-5.", ["|2"] = "Activating the Waters of Oblivion will spawn the NM Tros.", ["|3"] = "Click on the Waters of Oblivion once Tros is defeated for a cutscene."}},
    [64] = {s = {["|1"] = "Speak to Bki Tbujhja to begin the quest; she will request a flask of holy water.", ["|2"] = "Trade Bki Tbujhja the Holy Water and you will be asked to travel to The Eldieme Necropolis and to visit the tomb of a great bard of", ["|3"] = "Travel to The Eldieme Necropolis via (F-5) in Batallia Downs and head for a room with five unbroken sarcophagi at D-4.", ["|5"] = "Defeat all three NMs that spawn, then interact with the same sarcophagus again.", ["|6"] = "Return to Bki Tbujhja and receive your Choral Slippers."}},
    [65] = {s = {["|1"] = "Speak to Mertaire in Lower Jeuno, who tells you to take the Star ring (tarnished) to an antique collector.", ["|10"] = "Defeat him, then examine the altar again for a cutscene.", ["|11"] = "Return and speak to Chalvatot for your reward, and to complete the quest.", ["|2"] = "Speak to Imasuke (E-6) in Port Jeuno.", ["|3"] = "Travel to (I-10) in Xarcabard and examine the Perennial Snow at the end of the short tunnel.", ["|4"] = "Retrieve the Star ring (indecipherable) by examining the Perennial Snow.", ["|5"] = "Go back to Imasuke who tells you to find someone who can translate the ring.", ["|6"] = "Head to Chateau d'Oraguille and speak to Chalvatot at (F-7) to receive the Moon ring.", ["|7"] = "Listen to his instructions and travel to Monastic Cavern via Davoi @ (H-11)", ["|8"] = "Walk to the small circular room at (I-8) with the altar in it"}},
    [66] = {s = {["|1"] = "Speak to Kurou-Morou after completing the prerequisite quests.", ["|2"] = "Speak to Ilumida (Upper Jeuno G-8) until she gives you a cutscene requesting you obtain a Moondrop.", ["|3"] = "Travel to The Boyahda Tree and examine a ??? at H-8 in 2nd map of The Boyahda Tree between 19:00 and 04:00 to spawn an Ahriman NM Agas.", ["|4"] = "Once defeated, examine the ??? again between the hours of 19:00 and 04:00 to get the Moondrop.", ["|5"] = "Return to Upper Jeuno and talk to Ilumida for your reward.", ["|6"] = "You may speak to Kurou-Morou once more to see a cutscene, but it is not necessary for your reward."}},
    [67] = {s = {["|1"] = "Speak to Vola to begin this quest with Monk as your main job.", ["|2"] = "Exit the Tenshodo through the Door: \"Neptune's Spire\" to get a cutscene with Atori-Tutori.", ["|3"] = "Obtain a Wyrm Beard from Nidhogg or Early Bird Catches the Wyrm.", ["|4"] = "Speak to Degenhard, Bastok Markets (I-10).", ["|5"] = "Obtain a Behemoth Tongue from King Behemoth or Horns of War.", ["|6"] = "Speak to Maat, Ru'Lude Gardens (H-5).", ["|7"] = "Finally, trade a Brown Belt to the same door for the final cutscene and a Black Belt."}},
    [68] = {s = {["|1"] = "Speak to Taillegeas to begin this quest.", ["|2"] = "He will ask you to bring him a few of the following items:", ["|3"] = "Trade Taillegeas the items he requests for your reward."}},
    [69] = {s = {["|1"] = "Speak to Odasel outside Gems by Kshama (H-9) to begin this quest.", ["|2"] = "Travel to Lufaise Meadows and defeat the Gigas there until they drop a Chameleon Diamond.", ["|3"] = "Trade the Chameleon Diamond to Odasel to complete this quest.", ["|4"] = "Speak to Matoaka inside the shop for an additional cutscene."}},
    [71] = {s = {["|1"] = "Speak to Omer to begin this quest.", ["|2"] = "The item Omer asks for drops off Krakens fished up in Qufim Island.", ["|3"] = "Return the fishing rod to Omer for your reward.", ["|4"] = "The game will freeze on the cutscene if you have your FPS set to 60."}},
    [72] = {s = {["|1"] = "Speak to Nevela to begin this quest.", ["|2"] = "Go to Bastok Mines and talk to Wobke (I-9).", ["|3"] = "Go to Pashhow Marshlands Outpost and examine the Outpost Gate for a cutscene.", ["|4"] = "Obtain three Warding Oils from Emerald Quadav in Beadeaux.", ["|5"] = "Trade the oils to the Outpost Gate for a cutscene.", ["|6"] = "Go to Bastok Mines and speak to Wobke.", ["|7"] = "Head to Batallia Downs and examine the ??? on a headstone located at (H-6) to spawn 5 NM tigers called Badshah.", ["|8"] = "Kill Badshah and re-examine the ??? to obtain Silver Comet's collar.", ["|9"] = "Speak to Nevela to complete the quest."}},
    [73] = {s = {["|1"] = "In Upper Jeuno, speak to Migliorozz (H-9), Temple of the Goddess) who will give you either a Phoenix pearl or a Phoenix armlet.", ["|10"] = "Return back to the entrance of this tower in the room with the stairwell (I-8) or by whatever means is fastest for you:", ["|11"] = "Return upstairs (I-8), go down this hall (where the you acquired the Blue bracelet earlier) towards the end of the path where a green door", ["|12"] = "Head to (G-8) where you will find a Crystal Receptor.", ["|13"] = "Examine the Crystal Receptor and quickly head back down the hall you came from to drop down the hole you passed by (H-9), labeled \"Drop B\"", ["|14"] = "Head down the elevator and examine the Avatar Gate on the West side of the circular room you're in for a cutscene.", ["|15"] = "Return to Migliorozz for your reward.", ["|2"] = "Head to Beaucedine Glacier and enter Pso'Xja from the tower at (G-9).", ["|3"] = "Go up the stairs and into the small room at (I-8) where you will find a ???.", ["|4"] = "When you examine the ???, Gargoyle-Iota and Gargoyle-Kappa will spawn.", ["|5"] = "Examine the ??? once the NM's are defeated to obtain a Blue bracelet.", ["|6"] = "Head down the stairs to (H-9) where you will find a blue door that only opens if you have a Blue bracelet.", ["|7"] = "Drop down the hole and head to (H-7) where you will find another ???.", ["|8"] = "Checking the ??? will spawn Gargoyle-Lambda and Gargoyle-Mu.", ["|9"] = "Examine the ??? after the NM's are defeated to obtain a Green bracelet."}},
    [76] = {s = {["|1"] = "Talk to Maat at (H-5) in Ru'Lude Gardens on each job.", ["|5"] = "Upon defeating Maat for the last time, speak with him to receive the cutscene and your new Maat's Cap."}},
    [77] = {s = {["|1"] = "Speak to Luto Mewrilah to begin the quest.", ["|2"] = "Once you have selected a race and name, Luto Mewrilah will ask you to find out information about your fellow.", ["|3"] = "Speak to Akta - Ru'Lude Gardens (H-10) to choose your fellow's height: short, medium, or tall.", ["|4"] = "Speak to Kuah Dakonsa - Lower Jeuno (H-8) who will ask you to choose your fellow's face and hair.", ["|5"] = "Speak to Red Ghost - Port Jeuno (G-8) who will ask you about your fellow's personality.", ["|6"] = "Go to Upper Jeuno and speak to Bheem (F-5) for a cutscene.", ["|7"] = "Return to Luto Mewrilah to complete the quest."}},
    [81] = {s = {["|1"] = "Speak to Luto for a cutscene that begins the quest.", ["|2"] = "Touch the ??? spot for a brief cutscene; once it is finished the slime and your Adventuring Fellow will pop.", ["|4"] = "You will then need to go to the northern part of the lake in Jugner Forest."}},
    [84] = {s = {["|1"] = "Speak to Luto for a cutscene to begin the quest.", ["|4"] = "Go to Windurst Waters north map (F-10) and speak to Chamama in the Rarab Tail Hostelry to receive Jar of reversion dust.", ["|6"] = "Once you defeat the magic pot, speak to your Adventuring Fellow, then examine the ??? spot for a final cutscene that ends the quest."}},
    [85] = {s = {["|1"] = "Speak to Luto for a cutscene that begins the quest.", ["|5"] = "Return to Luto in Upper Jeuno for a cutscene, then speak to Monberaux for a cutscene that completes the quest."}},
    [86] = {s = {["|1"] = "After finishing all of the cutscenes after Dawn including Blueblade Fell, walk towards the Palace in Ru'Lude Gardens to begin the cutscene.", ["|2"] = "Examine the Dilapidated Gate in Misareaux Coast (F-7) for a cutscene.", ["|3"] = "Head to the Unstable Displacement in the northwest section of Riverne - Site #B01 (E-7) for a cutscene.", ["|5"] = "Defeat Bahamut for another cutscene.", ["|6"] = "Return to the Palace in Ru'Lude Gardens for a cutscene that completes the quest."}},
    [88] = {s = {["|1"] = "Note: You need to wait until the next in-game day to activate this quest to trigger the cutscene for this quest where you receive the", ["|2"] = "Walk into the palace in Ru'Lude Gardens for a cutscene and the Note written by Esha'ntarl.", ["|3"] = "Visit three Promyvions (through the Shattered Telepoints and the middle Cermet Gate) and get the following key items from the Memory Fluxes", ["|4"] = "Return to the palace in Ru'Lude Gardens for a final cutscene with Esha'ntarl."}},
    [89] = {s = {["|1"] = "Note: You must zone and wait until the next game day after completing the previous quest.", ["|10"] = "See the Discussion page for testimonials.", ["|11"] = "After defeating the brothers, speak to Aldo in Lower Jeuno (J-8) for a cutscene.", ["|12"] = "Zone and wait until the next Vana'diel day after completing the battlefield, then talk to Gilgamesh in Norg for a cutscene to complete the", ["|2"] = "Enter the palace in Ru'Lude Gardens.", ["|3"] = "Zone into Sealion's Den for a cutscene and then speak with Sueleen to head to Al'Taieu.", ["|4"] = "Zone into the Grand Palace of Hu'Xzoi and click the entrance to The Garden of Ru'Hmet (Gate of the Gods) for a cutscene.", ["|5"] = "Go to the Empyreal Paradox and check the Transcendental Radiance for a cutscene.", ["|6"] = "Check the Transcendental Radiance again to enter the BC against Eald'narche and Kam'lanaut.", ["|7"] = "This fight was initially uncapped at level 75.", ["|8"] = "Trusts may be summoned inside this fight.", ["|9"] = "In this BC you fight both Kam'lanaut and his brother Eald'narche at the same time."}},
    [90] = {s = {["|1"] = "Speak with Ajithaam to recieve a White Sentinel badge and begin the quest.", ["|2"] = "Speak with the following people:", ["|3"] = "Once you have spoken to all 20 people, return to Ajithaam.", ["|5"] = "After joining Salaheem's Sentinels, Ajithaam will offer to teleport you to Aht Urhgan Whitegate."}},
    [91] = {s = {["|1"] = "Talk to Faursel (Neptune's Spire J-8) for a cutscene.", ["|2"] = "He will give you three options to choose from.", ["|3"] = "Talk to Faursel a second time for another cutscene and choose \"I want to go\".", ["|4"] = "Faursel will give you four ways to proceed: the Advanced path, the Intermediate path, the Beginner path, or paying 500,000 Gil.", ["|5"] = "Collect the required item(s) for Faursel.", ["|6"] = "Trade the requested item(s) to him.", ["|7"] = "Zone and return to Lower Jeuno the next game day."}},
    [92] = {s = {["|1"] = "Head to Upper Jeuno and speak to Brutus at (G-7).", ["|2"] = "Head to La Theine Plateau and check the Chocobo Tracks at the far northwest corner of (E-5), just south of the sliver of map in (E-4).", ["|3"] = "Return to Upper Jeuno and speak to Brutus (G-7) again.", ["|4"] = "Head to Southern San d'Oria and speak to Hantileon (I-11).", ["|5"] = "Return to Brutus (G-7) in Upper Jeuno one last time to complete the quest.", ["|6"] = "Speak to Brutus (G-7) after one game day to receive a chocobo egg."}},
    [95] = {s = {["|1"] = "Speak with Laila at (G-7) in Upper Jeuno to begin the quest.", ["|2"] = "She will then ask for a Stardust pebble.", ["|3"] = "Speak with the mithran dancer Rhea Myuliah next to her.", ["|4"] = "Head to Lion Springs Tavern at (K-6) in Southern San d'Oria and speak to Valderotaux at the bar to \"dance\" and underwhelm him.", ["|5"] = "Return to Rhea Myuliah in Upper Jeuno to discover what the pebbles are.", ["|6"] = "Travel to the past and go to (I-5) in Jugner Forest (S).", ["|7"] = "Touch the glowing pebbles targetable location near the shore for a cutscene and to receive the Stardust pebble.", ["|8"] = "Speak with Laila in Upper Jeuno once more to finish the quest."}},
    [96] = {s = {["|1"] = "Speak to Laila in Upper Jeuno (G-7).", ["|2"] = "Speak to Rhea Myuliah next to Laila in Upper Jeuno (G-7).", ["|3"] = "Head to Grauberg (S) and examine the ??? in Witchfire Glen at (F-5) for a cutscene.", ["|4"] = "Examine the ??? again to spawn the NM Migratory Hippogryph.", ["|5"] = "Examine the ??? after defeating the NM for a cutscene to receive the The Essence of Dance.", ["|6"] = "\"Open\" the Key Item: The Essence of Dance.", ["|7"] = "Speak to Laila in Upper Jeuno (G-7) for a cutscene and your reward."}},
    [97] = {s = {["|1"] = "Speak to Laila in Upper Jeuno (G-7).", ["|2"] = "Zone into Jugner Forest (S) for a cutscene.", ["|3"] = "Examine the Glowing Pebbles in Jugner Forest (S) (I-5) for a cutscene.", ["|4"] = "Trade the Yagudo Glue to the Glowing Pebbles in Jugner Forest (S) (I-5).", ["|5"] = "Speak to Laila in Upper Jeuno (G-7) for a cutscene and your reward."}},
    [98] = {s = {["|1"] = "Speak to Laila in Upper Jeuno (G-7) for a cutscene and Wyatt's proposal.", ["|2"] = "Speak to Harmodios in Bastok Markets (K-10) inside the music shop.", ["|3"] = "Return to Upper Jeuno and speak to Laila again.", ["|4"] = "Speak to Rhea Myuliah in Upper Jeuno (G-7).", ["|5"] = "After you feel comfortable with performing in front of the audience, speak with Laila.", ["|6"] = "The audience is composed of 3 children, 2 young men/women, and 2 older people.", ["|7"] = "Perform the best to complete the quest and receive your reward."}},
    [99] = {s = {["|1"] = "Speak to Laila as a level 66 Dancer or higher to begin this quest.", ["|5"] = "Bring Laila to approximately 25% HP to win the fight."}},
    [100] = {s = {["|1"] = "Speak to Rakuru-Rakoru in Lower Jeuno (I-6) next to the fountain.", ["|2"] = "Speak with Rakuru-Rakoru at any time to check your progress.", ["|3"] = "Once all the NM data has been recorded return to Rakuru-Rakoru for your reward.", ["|4"] = "The reward of 59630 gil: when these numbers are pronounced in Japanese, it says \"gokurousama\" which translates to \"I appreciate the effort\"."}},
    [101] = {s = {["|1"] = "Speak with Luto Mewrilah for a cutscene that begins the quest.", ["|2"] = "Go to the Qu'Bia Arena in Fei'Yin (Home Point #1) to enter the battlefield.", ["|3"] = "Once your Fellow reaches 10%-20% HP, he/she will give up."}},
    [128] = {s = {["|1"] = "Speak to Maat on a level 50 job.", ["|2"] = "You may either defeat monsters in order to obtain the required items or select three ???s on the ground in the zones to obtain the key", ["|3"] = "If you wish to fight the monsters for the drop as opposed to collecting key items, Trusts will be sufficient for this purpose.", ["|4"] = "Bomb Coal which drops from Explosures or can be received after obtaining three Bomb coal fragments from ??? targets in Garlaige Citadel.", ["|5"] = "Exoray Mold which drops from Exorays (U) or can be received after obtaining three Exoray mold crumbs from ??? targets in Crawler's Nest", ["|6"] = "Ancient Papyrus which drops from Liches (C) or can be received after obtaining three Ancient papyrus shreds from ??? targets in The Eldieme", ["|7"] = "Trade the items to Maat to complete the quest."}},
    [129] = {s = {["|1"] = "Speak to Maat on a level 51 job.", ["|3"] = "The Notorious Monsters stand guard in caves have fairly large aggro range and will respawn within about 5 minutes after being defeated.", ["|7"] = "You also solo these Notorious Monsters now with relative ease using Trusts.", ["|9"] = "Speak to Maat once you have all three key items to complete the quest."}},
    [130] = {s = {["|3"] = "Speak to Maat on a level 56 job.", ["|38"] = "Return to Jeuno and speak to Maat once you have all three key items."}},
    [131] = {s = {["|1"] = "Speak to Maat on a level 61+ job.", ["|5"] = "Speak to Maat once you have all four stones to complete the quest."}},
    [132] = {s = {["|28"] = "Return to Ru'Lude Gardens and speak to Maat to complete the quest. *as of 2026 he doesn't appear to have post-win dialogue other than when", ["|3"] = "Speak to Maat on any level 66-70 Job.", ["|5"] = "Once you trade the testimony to Maat, he will ask if you are ready."}},
    [133] = {s = {["|1"] = "Speak to the Nomad Moogle in Ru'Lude Gardens at (H-5).", ["|2"] = "Trade the Nomad Moogle 5 Kindred's Seals while having 3 Merit Points to complete the quest."}},
    [134] = {s = {["|1"] = "Speak to the Nomad Moogle in Ru'Lude Gardens at (H-5).", ["|2"] = "Trade the Nomad Moogle 5 Kindred's Crests while having 4 merit points to complete the quest."}},
    [135] = {s = {["|1"] = "Speak to the Nomad Moogle in Ru'Lude Gardens at (H-5).", ["|2"] = "Trade 10 Kindred's Crests to the Nomad Moogle while also having 5 merit points.", ["|5"] = "Win at the mini-game and you will receive your reward."}},
    [136] = {s = {["|1"] = "Speak to the Nomad Moogle in Ru'Lude Gardens at (H-5).", ["|16"] = "Trade 1 Kindred's Crest and the requested item to the Nomad Moogle while having 10 merit points.", ["|18"] = "When the Nomad Moogle tells you to start, wait ten seconds and then select \"Push!\"."}},
    [137] = {s = {["|1"] = "After completing the previous quest, the Nomad Moogle will give you the option to warp to a BCNM.", ["|6"] = "Warp back and talk to the Nomad Moogle to have your level limit increased, and to finish this quest."}},
    [160] = {s = {["|1"] = "Speak with Luto Mewrilah for a cutscene that begins the quest and provides the Magian Mooglehood missive.", ["|6"] = "Trade the Copper Meed to Luto Mewrilah to complete the quest."}},
    [161] = {s = {["|1"] = "Speak with Luto Mewrilah for a cutscene that begins the quest and provides the Magian Mooglehood missive.", ["|6"] = "Trade the Silver Meed to Luto Mewrilah to complete the quest."}},
    [162] = {s = {["|1"] = "Speak with Luto Mewrilah for a cutscene that begins the quest and provides the Magian Mooglehood missive.", ["|6"] = "Trade the Mythril Meed to Luto Mewrilah to complete the quest."}},
    [163] = {s = {["|1"] = "Speak with Luto Mewrilah for a cutscene that begins the quest and provides the Magian Mooglehood missive.", ["|7"] = "Trade the Dark Meed to Luto Mewrilah to complete the quest."}},
    [164] = {s = {["|1"] = "Speak with Luto Mewrilah for a cutscene that begins the quest and the Magian Mooglehood missive", ["|7"] = "Trade the Gold Meed with x20 Kindred's Crest to Luto Mewrilah to complete the quest"}},
    [166] = {s = {["|1"] = "Speak to Chululu", ["|2"] = "You will randomly be given five of one of the following cards:", ["|3"] = "Trade with other players until you have at least one of all of the cards.", ["|4"] = "Trade all four cards to Chululu for your measly reward.", ["|5"] = "Note: Every real-life day you can obtain another five cards from Chululu."}},
    [167] = {s = {["|1"] = "Talk to the Nomad Moogle near Maat.", ["|2"] = "Give him 15 merits to receive Heart of the bushin, which allows you to access the Merit Weapon Skills.", ["|3"] = ">=357 Skill in a weapon is required to use the Merit Weapon Skills, but not necessary to complete this quest."}},
    [170] = {s = {["|1"] = "Talk to the Nomad Moogle next to Maat to begin the quest.", ["|2"] = "Retrieve a Seasoning Stone, which drops off nearly all level 90+ regular monsters outside of Abyssea and trade it to the Nomad Moogle.", ["|3"] = "You will receive Soul gem clasp and access to the level 95 cap fight, Beyond Infinity.", ["|4"] = "This quest is now technically completed."}},
    [175] = {s = {["|1"] = "After completing The Geomagnetron, return to Darcia and ask if she has more work for you.", ["|2"] = "Darcia will grant you a Temporary geomagnetron and ask you to return to one of the Geomagnetic Founts.", ["|3"] = "Travel to one of the locations and attune the device to the Geomagnetic Fount found there.", ["|4"] = "Return to Darcia to complete the quest."}},
    [176] = {s = {["|1"] = "Talk to Nantoto at H-8 in Lower Jeuno after you have completed 50 unique Records of Eminence quests.", ["|5"] = "Report back to Nantoto for a short cutscene to complete the quest and obtain the 3 Copper Vouchers."}},
    [177] = {s = {["|1"] = "Talk to Nantoto at H-8 in Lower Jeuno after you have completed 100 unique Records of Eminence quests.", ["|5"] = "Report back to Nantoto for a short cutscene to complete the quest and obtain the 5 Copper A.M.A.N Vouchers."}},
    [178] = {s = {["|1"] = "Talk to Nantoto at H-8 in Lower Jeuno.", ["|4"] = "Return to Nantoto for a cutscene and your reward."}},
    [179] = {s = {["|1"] = "Speak to Mapitoto on any job level 20 or higher.", ["|2"] = "Accept the offer to feed her Raptor as it is trying to bite off her nose like it's a little-wittle sausage.", ["|3"] = "She will mark several locations on your map to go.", ["|4"] = "Travel to the points on the map.", ["|5"] = "The raptor will get agitated and slower as you take longer to get to the food.", ["|6"] = "Successfully feeding the raptor will result in a message notifying you that it has \"overcome the munchies\".", ["|7"] = "Once you have successfully fed the raptor rendezvous with Syrillia at (E-6) who will warp you back.", ["|8"] = "A comfortable example route: J-8 > /cheer > I-7 > H-6 > /cheer > G-6 > F-7 > /cheer > E-6", ["|9"] = "Return to Mapitoto in Upper Jeuno for your reward."}},
    [186] = {s = {["|18"] = "Trade the stacks of Clusters to obtain the Whirring engine Key Item.", ["|19"] = "Return to Mapitoto to get the Levitus key Key Item.", ["|3"] = "Complete the The Celestial Nexus II, on any difficulty, to get the Broken flying machine Key Item.", ["|8"] = "Obtain a Ve'Lugannon Coffer Key and open a coffer in Ve'Lugannon Palace to obtain the Levitation device Key Item."}},
}
